42	// word boundary only at j = 2 and j = 5, and in both the next word exists, so
43	// there is no guard on the high half beyond the shift that makes it zero.
44	void q4kScaleMin12(uint j, uvec4 s, out uint sc, out uint mn) {
45	    uint b = j * 12u;
46	    uint w = b >> 5, o = b & 31u;
47	    uint v = s[w] >> o;
48	    if (o > 20u) {
49	        v |= s[w + 1u] << (32u - o);
50	    }
51	    sc = v & 63u;
52	    mn = (v >> 6) & 63u;
53	}

