	// What a token reads is less than what is staged: the columns past the
	// split are staged and skipped.
	read := q4kBytes(g.q8Split(), wide) + q4kBytes(n, wide) - q4kBytes(n, wide) + tail +
		q4kBytes(wide, cfg.LowRank) + (q4kBytes(n, wide) - n*wide/2)
	t.Logf("read %.2f MB a token against the fp16 bank's %.2f", float64(read)/1e6, float64(half)/1e6)
	if ratio := float64(half) / float64(read); ratio < 2.2 || ratio > 2.9 {
		t.Fatalf("a token reads %.3fx less than on halves, want ~2.5", ratio)
	}
}
